import { Injectable } from '@angular/core';
import { ApiServiceService } from '../../../services/api/api-service.service';
import { firstValueFrom } from 'rxjs';
import { Credito } from '../../../models/credito.model';
import { EstadoCuentaService } from '../../../controllers/estado.cuenta.service';

@Injectable({
  providedIn: 'root'
})
export class ConsolidadoHistoricoService {
  endpoint = 'api/consolidado/historico'
  data: Credito[] = []

  constructor(
    private api: ApiServiceService,
    private estadoCuentaController: EstadoCuentaService,
  ) { }

  public async fetchData(options: {
    inicio?: string;
    fin?: string;
    producto_financiero_id?: number | null;
  }) {
    if (!this.data.length) {
      await this.initData()
    }
    return this.data
      .filter(c => {
        // 1. Filtrar por producto financiero
        if (options.producto_financiero_id && c.productos_financiero_id != options.producto_financiero_id) {
          return false;
        }

        if (!c.liberado_fecha) {
          return false;
        }

        if(c.estado==='CANCELADO'){
          return false;
        }

        // 2. Si no hay fechas para filtrar, retorna true
        if (!options.inicio && !options.fin) {
          return true;
        }

        if (!c.fecha_convenio && !c.created_at && !c.formalizado_fecha) {
          return false;
        }

        // 3. CORRECCIÓN: Usar el campo correcto (fecha_inicio en lugar de fecha_convenio)
        let fechaConvenio = new Date(c.fecha_convenio ?? c.liberado_fecha ?? c.formalizado_fecha ?? c.created_at);

        // 4. Filtrar por fecha de inicio (sin problemas de zona horaria)
        if (options.inicio) {
          const inicioDate = new Date(options.inicio);
          // Establecer al inicio del día (00:00:00) en la zona horaria local
          inicioDate.setHours(0, 0, 0, 0);

          if (fechaConvenio < inicioDate) {
            return false;
          }
        }

        // 5. Filtrar por fecha de fin
        if (options.fin) {
          const finDate = new Date(options.fin);
          // Establecer al final del día (23:59:59) en la zona horaria local
          finDate.setHours(23, 59, 59, 999);

          if (fechaConvenio > finDate) {
            return false;
          }
        }

        return true;
      });
  }

  private async initData() {
    // Primero, obtener el número total de páginas
    const firstPage = await firstValueFrom(
      this.api.get<Credito[]>(this.endpoint, { page: 1, per_page: 1000 }, false)
    );
    const lastPage = firstPage.total_pages ?? 0;

    // Generar todas las páginas
    const pages = Array.from({ length: lastPage }, (_, i) => i + 1);

    // Procesar en lotes de 5 páginas simultáneas
    const chunkSize = 5;
    for (let i = 0; i < pages.length; i += chunkSize) {
      const chunk = pages.slice(i, i + chunkSize);
      const promises = chunk.map(page =>
        firstValueFrom(this.api.get<Credito[]>(this.endpoint, { page, per_page: 1000 }, false))
          .then(res => { 
            return res.data ?? []
          })
      );

      const results = await Promise.all(promises);
      results.forEach(data => this.data.push(...data));
    }
  }
}
