import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable, forkJoin, from, of } from 'rxjs';
import { switchMap, concatMap, toArray, tap, catchError, map, reduce } from 'rxjs/operators';
import { Conditional, Paginator } from '../../../controllers/super.service';
import { SolicitudApoyo } from '../../../models/solicitud.apoyo';
import { SolicitudApoyoService } from '../../../controllers/solicitud.apoyo.service';

@Injectable({
  providedIn: 'any'
})
export class FetchDataApoyosService {
  private progressSubject = new BehaviorSubject<number>(0);
  public progress$ = this.progressSubject.asObservable();

  constructor(private solicitudApoyoController: SolicitudApoyoService) { }

  public getAllData(fetchExtra?:{
    conditionals?: (Partial<SolicitudApoyo>) | (Conditional[]) | (undefined),
    relations?: string[] | undefined,
    extraData?: Record<string, any> | undefined
  }): Observable<SolicitudApoyo[]> {
    return this.dataLength(fetchExtra).pipe(
      switchMap(totalItems => {
        const chunkSize = 100;
        const lastChunk = Math.ceil(totalItems / chunkSize);
        //const lastChunk = 3;
        let loadedItems = 0;

        // Crear un array de números de página (1, 2, 3... lastChunk)
        const pages = Array.from({ length: lastChunk }, (_, i) => i + 1);
        const paginator={
          page:1,
          per_page: chunkSize,
        }
        if(!fetchExtra){
          fetchExtra={
            relations:['*']
          }
        }
        if(fetchExtra && !fetchExtra.relations){
          fetchExtra.relations=['*']
        }
        if(!fetchExtra.conditionals){
          fetchExtra.conditionals={
            deleted_at:null,
          }
        }

        // Convertir el array en un Observable que emite cada página secuencialmente
        return from(pages).pipe(
          // Ejecutar cada petición en secuencia
          concatMap(page => {
            paginator.page=page
            return this.fetchData(fetchExtra?.conditionals, paginator, fetchExtra?.relations, fetchExtra?.extraData).pipe(
              tap(data => {
                loadedItems += data.length;
                this.progressSubject.next(Math.round((loadedItems / totalItems) * 100));
              })
            );
          }),
          // Acumular todos los resultados en un solo array
          reduce((acc: SolicitudApoyo[], data: SolicitudApoyo[]) => [...acc, ...data], []),
          catchError(error => {
            console.error('Error loading data:', error);
            return of([]);
          })
        );
      })
    );
  }

  private dataLength(
    fetchExtra?:{
      conditionals?: (Partial<SolicitudApoyo>) | (Conditional[]) | (undefined),
      relations?: string[] | undefined,
      extraData?: Record<string, any> | undefined
    }
  ): Observable<number> {
    return from(this.solicitudApoyoController.get(
      fetchExtra?.conditionals,
      { per_page: 1, page: 1 },
      [],
      { 
        sort: JSON.stringify({ column: 'id', desc: true }),
        ...fetchExtra?.extraData,
      }, false
    )).pipe(
      map(res => res.total_items ?? 0),
      catchError(() => of(0))
    );
  }

  private fetchData(
    conditionals: (Partial<SolicitudApoyo>) | (Conditional[]) | undefined = undefined,
    paginator: Paginator | undefined = undefined,
    relations: string[] | undefined = undefined,
    extraData: Record<string, any> | undefined = undefined
  ): Observable<SolicitudApoyo[]> {
    return from(this.solicitudApoyoController.get(
      conditionals,
      paginator,
      relations,
      extraData, false
    )).pipe(
      map(res => res.data ?? []),
      catchError(() => of([]))
    );
  }
}
