  /**
 * Calcula la edad a partir de una fecha de nacimiento
 * @param fechaNacimiento Puede ser un string (YYYY-MM-DD), Date object o timestamp
 * @returns Edad en años (número entero)
 */
  private calcularEdad(fechaNacimiento?: string | Date | number): number | undefined {
    if (!fechaNacimiento) return;
    // Convertir a objeto Date si no lo es
    const fechaNac = new Date(fechaNacimiento);

    // Validar que la fecha sea válida
    if (isNaN(fechaNac.getTime())) {
      return
    }

    const hoy = new Date();
    let edad = hoy.getFullYear() - fechaNac.getFullYear();
    const mes = hoy.getMonth() - fechaNac.getMonth();

    // Ajustar si aún no ha pasado el mes de cumpleaños
    // o si es el mes pero no ha pasado el día
    if (mes < 0 || (mes === 0 && hoy.getDate() < fechaNac.getDate())) {
      edad--;
    }

    return edad;
  }

  public getYesterdayDate(): string {
    const yesterday = new Date();
    yesterday.setDate(yesterday.getDate() - 1);
    return yesterday.toISOString().split('T')[0];
  }

  public async fetchDataConsolidado() {
    this.isLoadingConsolidado = true;
    this.progressConsolidado = 0
    for (let i = 1; i < 9; i++) {
      setTimeout(() => { this.progressConsolidado += 10 }, 1500 * i)
    }
    setTimeout(() => { this.progressConsolidado += 19 }, 12000)

    this.fetchDataService.progress$.subscribe(progress => {
      this.progressConsolidado = progress;
    });

    this.creditos = await this.consolidadoController.fetchData({
      inicio: this.inicioConsolidado,
      fin: this.finConsolidado,
      producto_financiero_id: this.productoFinancieroId
    })

    this.creditos = Array.from(
      new Map(this.creditos.map(credito => [credito.id, credito])).values()
    );

    setTimeout(() => { this.progressConsolidado = 100 }, 500)
    setTimeout(() => { this.isLoadingConsolidado = false }, 700)
    console.log(this.creditos)
  }

